sksl:
uniform shader image;
uniform shader blurred;
uniform float2 size;
uniform float4 screen;
uniform float time;
uniform float blurRadius;
uniform float amount;
uniform float threshold;
uniform float showMask;
uniform float maskColor;
uniform float style;
half softGate(half d, half t)
{
    if (t <= 0.0) return 1.0;
    return smoothstep(t, t + max(t * 0.5, half(0.001)), abs(d));
}
half4 main(float2 coord)
{
    half4 c = image.eval(coord);
    if (c.a <= 0.001) return half4(0.0);
    half3 col = c.rgb / c.a;
    if (showMask > 0.5 && maskColor > 0.5) {
        half4 b = blurred.eval(coord);
        half3 away = col - b.rgb / max(c.a, b.a);
        half lit = clamp((abs(dot(away, half3(0.2126, 0.7152, 0.0722))) - half(threshold - 0.5)) * 16.0, 0.0, 1.0);
        return half4(lit * c.a, 0.0, 0.0, c.a);
    }
    float sigma = max(blurRadius, 0.0) * 62.5 * min(screen.z, screen.w) / 1080.0;
    half3 soft = col;
    if (sigma > 0.05) {
        float4 sum = float4(c);
        float total = 1.0;
        for (int i = 0; i < 64; i++) {
            float r = sqrt((float(i) + 0.5) / 64.0) * 2.5 * sigma;
            float t = float(i) * 2.3999632;
            float w = exp(-0.5 * r * r / (sigma * sigma));
            sum += w * float4(image.eval(coord + r * float2(cos(t), sin(t))));
            total += w;
        }
        soft = half3(sum.rgb / total) / max(c.a, half(sum.a / total));
    }
    half3 diff = col - soft;
    half t = half(max(threshold - 0.5, 0.0) * 0.25);
    half3 g = half3(softGate(diff.r, t), softGate(diff.g, t), softGate(diff.b, t));
    if (style > 0.5) { half e = half(0.0425 + 0.09 * clamp(threshold, 0.0, 1.0)); g = half3(smoothstep(e, e + e, abs(dot(diff, half3(0.2126, 0.7152, 0.0722))))); }
    half3 corrected = clamp(col + half(amount) * diff * g, half3(0.0), half3(1.0));
    half3 ad = abs(diff);
    half m = clamp((ad.r + ad.g + ad.b) * half(1.3333333), 0.0, 1.0);
    if (showMask > 0.5) return half4(half3(m) * c.a, c.a);
    return half4(corrected * c.a, c.a);
}
